-- 2026-10-31j: MP Background timelines for batch 10, 25 more of the most viewed MPs (owner's approval, "yes", 31 Oct 2026).
-- Sets background_timeline (331 entries, copied exactly from "background-batch10.json", which is not committed) and
-- background_last_checked = 2026-10-31 for member_ids 3966, 3997, 4083, 4403, 4657, 4739, 4753, 4781, 4806, 4872, 5000, 5049, 5069, 5072, 5080, 5101, 5111, 5114, 5137, 5158, 5170, 5174, 5185, 5349, 5355,
-- each only WHERE background_timeline IS NULL. Every array passed lib/background-timeline.ts validate(). Every source link was checked by Cowork
-- before the data file was written.
-- Nothing else changes. No code change. Backup of the 25 rows, off the repo: "Claude outputs/backups/2026-10-31j-mp-biography-before.csv".
-- Guards (RAISE): exactly 25 rows change, all of them these 25; the 171 existing timelines are unchanged (md5);
-- MPs with a timeline go from 171 to 196; each array equals the file exactly; 2770 entries in all afterwards.
-- Undo: 2026-10-31j-UNDO.sql.
\set ON_ERROR_STOP on
BEGIN;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography WHERE member_id IN (3966, 3997, 4083, 4403, 4657, 4739, 4753, 4781, 4806, 4872, 5000, 5049, 5069, 5072, 5080, 5101, 5111, 5114, 5137, 5158, 5170, 5174, 5185, 5349, 5355)) <> 25 THEN RAISE EXCEPTION 'expected 25 biography rows'; END IF;
  IF EXISTS (SELECT 1 FROM public.mp_biography WHERE member_id IN (3966, 3997, 4083, 4403, 4657, 4739, 4753, 4781, 4806, 4872, 5000, 5049, 5069, 5072, 5080, 5101, 5111, 5114, 5137, 5158, 5170, 5174, 5185, 5349, 5355) AND background_timeline IS NOT NULL) THEN RAISE EXCEPTION 'a new MP already has a timeline'; END IF;
  IF (SELECT count(*) FROM public.mp_biography WHERE background_timeline IS NOT NULL) <> 171 THEN RAISE EXCEPTION 'expected 171 MPs with a timeline before'; END IF;
END $$;

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h, md5(coalesce(background_timeline::text, '')) AS th, (background_timeline IS NOT NULL) AS had
  FROM public.mp_biography b;

CREATE TEMP TABLE bt_new (member_id integer PRIMARY KEY, n integer NOT NULL, tl jsonb NOT NULL) ON COMMIT DROP;
